#include <LiquidCrystal.h>
#include <math.h>

// =====================================================
// 1. PIN CONFIGURATION
// =====================================================

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

const int LM35_PIN = A0;
const int MOISTURE_PIN = A1;

const int HEATER_PIN = 9;
const int FAN_PIN = 10;
const int PUMP_PIN = 8;

// =====================================================
// 2. TEMPERATURE SETTINGS
// =====================================================

const double SETPOINT = 25.0;

// Heater hysteresis
const double HEATER_ON_TEMP  = 24.0;
const double HEATER_OFF_TEMP = 25.0;

// Fan hysteresis
const double FAN_ON_TEMP  = 26.0;
const double FAN_OFF_TEMP = 25.0;

// =====================================================
// 3. SOIL MOISTURE SETTINGS
// =====================================================

const double MOISTURE_PUMP_ON  = 40.0;
const double MOISTURE_PUMP_OFF = 70.0;

// =====================================================
// 4. MOTOR SETTINGS
// =====================================================

const int MIN_PWM = 120;
const int MAX_PWM = 255;

// =====================================================
// 5. PID PARAMETERS
// =====================================================

double Kp = 45.0;
double Ki = 0.15;
double Kd = 1.5;

double integral = 0.0;
double previousError = 0.0;

// =====================================================
// 6. THERMAL SIMULATION MODEL
// =====================================================

const double HEATING_RATE = 0.20;
const double COOLING_RATE = 0.25;
const double PASSIVE_LOSS = 0.015;

double ambientTemperature = 25.0;
double simulatedTemperature = 25.0;

// =====================================================
// 7. CONTROLLER STATE
// =====================================================

int heaterPWM = 0;
int fanPWM = 0;

bool heaterEnabled = false;
bool fanEnabled = false;
bool pumpEnabled = false;

// =====================================================
// 8. TIMERS
// =====================================================

unsigned long lastControlTime = 0;
unsigned long lastLCDTime = 0;

// =====================================================
// 9. READ LM35
// =====================================================

double readLM35() {
  int sensorValue = analogRead(LM35_PIN);

  double voltage = sensorValue * (5.0 / 1023.0);

  // LM35 output = 10 mV per degree Celsius
  return voltage * 100.0;
}

// =====================================================
// 10. READ SOIL MOISTURE
// =====================================================

double readSoilMoisture() {
  int sensorValue = analogRead(MOISTURE_PIN);

  // Simulation mapping: ADC 0-1023 -> 0-100%
  // This is NOT a calibrated physical sensor reading.
  double moisture = (sensorValue / 1023.0) * 100.0;

  return constrain(moisture, 0.0, 100.0);
}

// =====================================================
// 11. MOTOR PWM CONTROL
// =====================================================

int calculateMotorPWM(double errorMagnitude) {
  double requestedPWM = 45.0 * errorMagnitude;

  requestedPWM = constrain(
    requestedPWM,
    0.0,
    (double)MAX_PWM
  );

  int pwm = (int)requestedPWM;

  if (pwm > 0 && pwm < MIN_PWM) {
    pwm = MIN_PWM;
  }

  return pwm;
}

// =====================================================
// 12. PID + HYSTERESIS TEMPERATURE CONTROLLER
// =====================================================

void updateController(double dt) {
  double error = SETPOINT - simulatedTemperature;

  // HEATER STATE CONTROL
  if (simulatedTemperature <= HEATER_ON_TEMP) {
    heaterEnabled = true;
  }
  else if (simulatedTemperature >= HEATER_OFF_TEMP) {
    heaterEnabled = false;
  }

  // FAN STATE CONTROL
  if (simulatedTemperature >= FAN_ON_TEMP) {
    fanEnabled = true;
  }
  else if (simulatedTemperature <= FAN_OFF_TEMP) {
    fanEnabled = false;
  }

  // Never run heater and fan simultaneously
  if (heaterEnabled) {
    fanEnabled = false;
  }

  if (fanEnabled) {
    heaterEnabled = false;
  }

  // PID CALCULATION
  integral += error * dt;

  integral = constrain(
    integral,
    -30.0,
    30.0
  );

  double derivative = 0.0;

  if (dt > 0.0) {
    derivative = (error - previousError) / dt;
  }

  double pidOutput =
      Kp * error +
      Ki * integral +
      Kd * derivative;

  previousError = error;

  // HEATER OUTPUT
  if (heaterEnabled) {
    heaterPWM = calculateMotorPWM(fabs(pidOutput));
    fanPWM = 0;
  }

  // FAN OUTPUT
  else if (fanEnabled) {
    fanPWM = calculateMotorPWM(fabs(pidOutput));
    heaterPWM = 0;
  }

  // BOTH OFF
  else {
    heaterPWM = 0;
    fanPWM = 0;
    integral = 0.0;
  }

  analogWrite(HEATER_PIN, heaterPWM);
  analogWrite(FAN_PIN, fanPWM);
}

// =====================================================
// 13. SOIL MOISTURE AND IRRIGATION CONTROLLER
// =====================================================

void updateIrrigationController() {
  double moisture = readSoilMoisture();

  // Start irrigation when moisture is 40% or lower
  if (moisture <= MOISTURE_PUMP_ON) {
    pumpEnabled = true;
  }
  // Stop irrigation when moisture is 70% or higher
  else if (moisture >= MOISTURE_PUMP_OFF) {
    pumpEnabled = false;
  }

  digitalWrite(
    PUMP_PIN,
    pumpEnabled ? HIGH : LOW
  );
}

// =====================================================
// 14. SIMULATED GREENHOUSE TEMPERATURE
// =====================================================

void updateTemperatureModel(double dt) {
  double heatingEffect =
      HEATING_RATE * ((double)heaterPWM / 255.0);

  double coolingEffect =
      COOLING_RATE * ((double)fanPWM / 255.0);

  double passiveEffect =
      PASSIVE_LOSS *
      (simulatedTemperature - ambientTemperature);

  simulatedTemperature +=
      (
        heatingEffect
        - coolingEffect
        - passiveEffect
      ) * dt;

  simulatedTemperature = constrain(
    simulatedTemperature,
    -20.0,
    100.0
  );
}

// =====================================================
// 15. LCD DISPLAY
// =====================================================

void updateLCD() {
  double moisture = readSoilMoisture();

  // First row: temperature
  lcd.setCursor(0, 0);

  lcd.print("Temp:");
  lcd.print(simulatedTemperature, 1);
  lcd.write((byte)223);
  lcd.print("C    ");

  // Second row: soil moisture and pump state
  lcd.setCursor(0, 1);

  lcd.print("M:");
  lcd.print((int)moisture);
  lcd.print("% ");

  if (pumpEnabled) {
    lcd.print("PUMP ON ");
  }
  else {
    lcd.print("PUMP OFF");
  }
}

// =====================================================
// 16. SETUP
// =====================================================

void setup() {
  pinMode(HEATER_PIN, OUTPUT);
  pinMode(FAN_PIN, OUTPUT);
  pinMode(PUMP_PIN, OUTPUT);

  analogWrite(HEATER_PIN, 0);
  analogWrite(FAN_PIN, 0);
  digitalWrite(PUMP_PIN, LOW);

  lcd.begin(16, 2);

  lcd.setCursor(0, 0);
  lcd.print("SMART GREENHOUSE");

  lcd.setCursor(0, 1);
  lcd.print("PID + IRRIGATION");

  delay(2000);

  // Read initial temperature from LM35
  ambientTemperature = readLM35();

  simulatedTemperature = ambientTemperature;

  previousError = SETPOINT - simulatedTemperature;

  lastControlTime = millis();
  lastLCDTime = millis();

  lcd.clear();
}

// =====================================================
// 17. MAIN LOOP
// =====================================================

void loop() {
  unsigned long now = millis();

  // Temperature control update every 100 ms
  if (now - lastControlTime >= 100) {
    double dt =
        (now - lastControlTime) / 1000.0;

    lastControlTime = now;

    updateTemperatureModel(dt);
    updateController(dt);
    updateIrrigationController();
  }

  // LCD refresh every 300 ms
  if (now - lastLCDTime >= 300) {
    lastLCDTime = now;
    updateLCD();
  }
}
